function evaluatePiece(piece, ctx = {}) {
  const errors = [];
  const warnings = [];
  const CHANNELS = ['instagram', 'linkedin_page', 'linkedin_profile'];
  const FORMATS = ['texto', 'imagen', 'carrusel', 'demo', 'reel'];
  const CATEGORIES = ['Educativo', 'Caso', 'Demo', 'Noticia', 'Evergreen', 'Founder'];
  const SOURCE_KINDS = ['hermes_research', 'real_work', 'evergreen', 'manual'];
  const CTA_TYPES = ['none', 'comment_keyword', 'resource', 'dm', 'link'];
  const LAYOUTS = ['cover', 'content', 'cta'];
  const FACTORS = { relevance: 15, audience_fit: 12, novelty: 8, evidence: 15, utility: 12, clarity: 10, conversation: 8, differentiation: 10, non_repetition: 10 };
  const THRESHOLD = 70;
  const isUrl = (u) => /^https?:\/\/[^\s/$.?#][^\s]*$/i.test(String(u || ''));
  const str = (v) => (typeof v === 'string' ? v.trim() : '');
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9% ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const fnv = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };

  const p = piece && typeof piece === 'object' ? piece : {};
  if (p.version !== 1) errors.push('version_invalida');
  if (!CHANNELS.includes(p.channel)) errors.push('canal_invalido');
  if (!FORMATS.includes(p.format)) errors.push('formato_invalido');
  if (!CATEGORIES.includes(p.category)) errors.push('categoria_invalida');
  const topic = str(p.topic);
  const angle = str(p.angle);
  const hook = str(p.hook);
  const body = str(p.body);
  if (topic.length < 5 || topic.length > 140) errors.push('topic_fuera_de_rango');
  if (!angle) errors.push('angle_obligatorio');
  if (!str(p.audience)) errors.push('audience_obligatoria');
  if (hook.length < 8 || hook.length > 160) errors.push('hook_fuera_de_rango');
  if (body.length < 40) errors.push('body_muy_corto');
  if (!str(p.rationale)) errors.push('rationale_obligatorio');
  if (!str(p.visual_direction) && ['imagen', 'carrusel', 'demo', 'reel'].includes(p.format)) errors.push('visual_direction_obligatoria');

  // Canal ↔ formato
  if (p.channel === 'instagram' && p.format === 'texto') errors.push('instagram_requiere_medio');
  const hashtags = Array.isArray(p.hashtags) ? p.hashtags.map(str).filter(Boolean) : [];
  if (hashtags.length > 5) errors.push('demasiados_hashtags');
  const ctaObj = p.cta && typeof p.cta === 'object' ? p.cta : { type: 'none' };
  if (!CTA_TYPES.includes(ctaObj.type || 'none')) errors.push('cta_tipo_invalido');
  if (ctaObj.type === 'comment_keyword' && (!str(ctaObj.keyword) || !str(ctaObj.resource))) errors.push('cta_keyword_requiere_keyword_y_recurso');
  if (ctaObj.type === 'resource' && !str(ctaObj.resource)) errors.push('cta_recurso_obligatorio');
  const ctaText = str(ctaObj.text);
  // Ola A · Resource & Conversation Engine v1: recurso asociado (opcional). «Comenta PALABRA → DM» NO está automatizado: la entrega es manual.
  if (p.cta_mode !== undefined && p.cta_mode !== null && !['none', 'resource_link', 'dm', 'diagnostic'].includes(p.cta_mode)) errors.push('cta_mode_invalido');
  if (p.resource_id !== undefined && p.resource_id !== null && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(p.resource_id))) errors.push('resource_id_invalido');
  if (p.cta_mode === 'resource_link' && !p.resource_id) errors.push('cta_resource_link_requiere_resource_id');
  if (p.resource_id && ctx.resourceChecked && !ctx.resource) errors.push('recurso_no_existe_o_no_activo');
  if (str(p.cta_copy).length > 240) errors.push('cta_copy_largo');
  if (ctaObj.type === 'comment_keyword') warnings.push('comment_keyword_sin_automatizacion_entrega_manual');

  // Texto final del post
  let postText = hook + '\n\n' + body;
  if (ctaText) postText += '\n\n' + ctaText;
  if (hashtags.length) postText += '\n\n' + hashtags.map((h) => (h.startsWith('#') ? h : '#' + h)).join(' ');
  const maxLen = p.channel === 'instagram' ? 2200 : 3000;
  if (postText.length > maxLen) errors.push('texto_excede_limite_' + maxLen);

  // Slides
  const slides = Array.isArray(p.slides) ? p.slides : [];
  if (['imagen', 'carrusel'].includes(p.format)) {
    const min = p.format === 'imagen' ? 1 : 3;
    const max = p.format === 'imagen' ? 1 : 10;
    if (slides.length < min || slides.length > max) errors.push('cantidad_de_slides_invalida');
  }
  const POSES = ['neutral', 'pregunta', 'celebra', 'senala', 'celular', 'brazos_arriba', 'laptop', 'conectada', 'tablet'];
  const EMOCIONES = ['neutral', 'pregunta', 'alegria', 'sorpresa', 'duda', 'salto', 'timida', 'orgullo', 'duerme'];
  let mascotCount = 0;
  slides.forEach((s, i) => {
    if (!LAYOUTS.includes(s && s.layout)) errors.push('slide_' + (i + 1) + '_layout_invalido');
    // Guía §6: la llamita es opcional, solo en portada o cierre, nunca en slides densos ni en todas las slides.
    if (s && s.mascot) {
      mascotCount++;
      const okPose = (s.mascot.sheet === 'poses' && POSES.includes(s.mascot.pose)) || (s.mascot.sheet === 'emociones' && EMOCIONES.includes(s.mascot.pose));
      if (!okPose) errors.push('slide_' + (i + 1) + '_mascota_invalida');
      if (s.layout === 'content') errors.push('slide_' + (i + 1) + '_mascota_solo_en_portada_o_cierre');
    }
    if (s && s.figure) {
      if (!str(s.figure.value) || str(s.figure.value).length > 12) errors.push('slide_' + (i + 1) + '_cifra_invalida');
      if (str(s.figure.label).length > 80) errors.push('slide_' + (i + 1) + '_cifra_etiqueta_larga');
    }
    if (s && s.compare) {
      const sides = [s.compare.left, s.compare.right];
      if (sides.some((c) => !c || !str(c.label) || str(c.label).length > 28 || str(c.text).length > 110)) errors.push('slide_' + (i + 1) + '_comparacion_invalida');
    }
    if (s && ((s.figure ? 1 : 0) + (s.compare ? 1 : 0) + (Array.isArray(s.items) && s.items.length ? 1 : 0)) > 1) errors.push('slide_' + (i + 1) + '_mezcla_de_estructuras');
    const t = str(s && s.title);
    if (!t) errors.push('slide_' + (i + 1) + '_sin_titulo');
    if (t.length > 90) errors.push('slide_' + (i + 1) + '_titulo_largo');
    if (str(s && s.body).length > 180) errors.push('slide_' + (i + 1) + '_texto_largo');
    if (Array.isArray(s && s.items) && s.items.length > 4) errors.push('slide_' + (i + 1) + '_muchas_ideas');
  });
  if (p.format === 'carrusel' && slides.length && slides[0].layout !== 'cover') warnings.push('primera_slide_no_es_portada');
  if (mascotCount > 2 || (slides.length > 2 && mascotCount > Math.ceil(slides.length / 2))) errors.push('demasiada_mascota');

  // Fuentes y claims
  const sources = Array.isArray(p.sources) ? p.sources : [];
  if (!sources.length) errors.push('sin_fuentes');
  sources.forEach((s, i) => {
    if (!SOURCE_KINDS.includes(s && s.kind)) errors.push('fuente_' + (i + 1) + '_tipo_invalido');
    if (!str(s && s.title)) errors.push('fuente_' + (i + 1) + '_sin_titulo');
    if (s && s.url && !isUrl(s.url)) errors.push('fuente_' + (i + 1) + '_url_invalida');
  });
  const evidenceUrls = (Array.isArray(p.evidence_urls) ? p.evidence_urls : []).map(str).filter(Boolean);
  if (evidenceUrls.some((u) => !isUrl(u))) errors.push('evidence_url_invalida');
  const verifiedSources = sources.filter((s) => s && s.verified === true);
  const claims = Array.isArray(p.claims) ? p.claims : [];
  claims.forEach((c, i) => {
    if (!str(c && c.text)) errors.push('claim_' + (i + 1) + '_sin_texto');
    if (c && c.external === true) {
      if (!isUrl(c.source_url)) errors.push('claim_externo_sin_fuente:' + str(c.text).slice(0, 40));
      else if (!verifiedSources.some((s) => s.url === c.source_url || (Array.isArray(s.evidence) && s.evidence.some((e) => e && e.url === c.source_url)))) errors.push('claim_externo_fuente_no_verificada:' + str(c.text).slice(0, 40));
    }
  });
  // Cifras / porcentajes en el texto deben tener respaldo en un claim
  const extra = (s) => [s && s.figure ? str(s.figure.value) + ' ' + str(s.figure.label) : '', s && s.compare ? [s.compare.left, s.compare.right].map((c) => (c ? str(c.label) + ' ' + str(c.text) : '')).join(' ') : ''];
  const allText = [hook, body, ctaText].concat(slides.map((s) => [s && s.kicker, s && s.title, s && s.body].concat(extra(s)).concat((s && s.items) || []).map((x) => (typeof x === 'object' && x ? str(x.title) + ' ' + str(x.text) : str(x))).join(' '))).join('\n');
  const claimBlob = norm(claims.map((c) => str(c && c.text)).join(' | '));
  const figures = allText.match(/\d[\d.,]*\s?%|\$\s?\d[\d.,]*|\d[\d.,]*\s?(millones|mil millones|veces)\b/gi) || [];
  figures.forEach((f) => { if (!claimBlob.includes(norm(f))) errors.push('cifra_sin_respaldo:' + f.trim()); });
  if (p.category === 'Noticia' && !claims.some((c) => c && c.external === true)) errors.push('noticia_sin_claim_externo');

  // Lint de marca / relleno de IA
  const BANNED = [/revolucion/i, /game.?changer/i, /en el mundo actual/i, /desbloque/i, /potencia tu/i, /el futuro (ya )?(est[aá]|es)/i, /innovador/i, /soluciones? integrales?/i, /sinergia/i, /disruptiv/i, /hoy m[aá]s que nunca/i, /llev(a|ar) (tu|su) negocio al siguiente nivel/i, /transformaci[oó]n digital/i, /en este post/i, /sum[eé]rgete/i, /\bdescubre c[oó]mo\b/i];
  let penalties = 0;
  const lintHits = [];
  BANNED.forEach((re) => { if (re.test(allText)) { penalties += 3; lintHits.push(String(re.source)); } });
  if (/agenda (una|tu) llamada/i.test(allText)) { penalties += 4; lintHits.push('cta_generico_agenda_llamada'); }
  if (/\bno sirve\b|somos mejores|mejor que (la competencia|otros)|garantizad[oa]|sin riesgo|el mejor del mercado/i.test(allText)) { penalties += 4; lintHits.push('ataque_o_promesa_exagerada'); }
  const emojiCount = (allText.match(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu) || []).length;
  if (emojiCount > 3) { penalties += 3; lintHits.push('exceso_de_emojis'); }
  // Ola B · Editorial Brain por canal: tipo editorial, tono/voz, largo, decisión visual y marca.
  const editorial = edEvaluate(p, { recentVisuals: ctx.recentVisuals });
  editorial.errors.forEach((e) => errors.push(e));
  editorial.warnings.forEach((w) => warnings.push(w));
  penalties += editorial.penalties;
  penalties = Math.min(penalties, 20);

  // Factores 0–10 (los asigna quien genera la pieza; aquí se validan, se acotan y se aplican topes)
  const f = p.factors && typeof p.factors === 'object' ? p.factors : {};
  const breakdown = {};
  let raw = 0;
  Object.keys(FACTORS).forEach((k) => {
    let v = Number(f[k] && typeof f[k] === 'object' ? f[k].value : f[k]);
    if (!Number.isFinite(v)) { errors.push('factor_faltante:' + k); v = 0; }
    v = Math.max(0, Math.min(10, v));
    if (k === 'evidence' && !verifiedSources.length) v = Math.min(v, 2);
    if (k === 'non_repetition' && Array.isArray(ctx.existingIdeaKeys)) { /* se fija abajo con idea_key */ }
    breakdown[k] = v;
  });
  const ideaKey = fnv(norm(p.channel) + '|' + norm(topic) + '|' + norm(angle));
  if (Array.isArray(ctx.existingIdeaKeys) && ctx.existingIdeaKeys.includes(ideaKey)) { errors.push('idea_repetida'); breakdown.non_repetition = 0; }
  Object.keys(FACTORS).forEach((k) => { raw += (FACTORS[k] * breakdown[k]) / 10; });
  const score = Math.max(0, Math.min(100, Math.round(raw - penalties)));

  let decision;
  if (errors.length) decision = 'rejected';
  else if (score >= THRESHOLD) decision = 'candidate';
  else decision = 'below_threshold';

  return { ok: errors.length === 0, decision, score, threshold: THRESHOLD, breakdown, penalties, lint_hits: lintHits, errors, warnings, idea_key: ideaKey, post_text: postText, evidence_urls: evidenceUrls, editorial: { type: editorial.type, inferred: editorial.inferred, visual_need: editorial.visual.need, visual_inferred: editorial.visual.inferred } };
}

function proposeSlot(o) {
  const tz = o.tz || 'America/Santiago';
  const now = Number(o.now);
  const SLOTS = { instagram: ['12:30', '19:00'], linkedin_page: ['10:00', '15:00'], linkedin_profile: ['09:00', '16:00'] };
  const cat = String(o.category || '');
  const tier = cat === 'Noticia' ? { name: 'noticia', minLeadH: 3, targetH: 24 } : cat === 'Evergreen' ? { name: 'evergreen', minLeadH: 12, targetH: 72 } : { name: 'normal', minLeadH: 12, targetH: 48 };
  const minMs = now + tier.minLeadH * 3600000;
  const warnings = [];
  const takenDays = {};
  (o.taken || []).forEach((t) => { if (t && Number.isFinite(Number(t.at)) && (!t.account || t.account === o.account)) takenDays[schedDayKey(Number(t.at), tz)] = true; });
  const free = (ms) => !takenDays[schedDayKey(ms, tz)];
  const label = (ms) => new Date(ms).toLocaleString('es-CL', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false });
  const done = (ms, source) => ({ iso: new Date(ms).toISOString(), ms, label: label(ms), tier: tier.name, hours_ahead: Math.round((ms - now) / 360000) / 10, target_hours: tier.targetH, within_target: ms - now <= tier.targetH * 3600000, source, warnings });
  // 1) fecha sugerida por Hermes: solo si es válida, está libre y cumple el plazo (o viene justificada)
  const sug = o.suggestion ? Date.parse(o.suggestion) : NaN;
  if (Number.isFinite(sug)) {
    const why = String(o.justification || '').trim();
    if (sug < minMs) warnings.push('sugerencia_muy_cercana_ignorada');
    else if (!free(sug)) warnings.push('sugerencia_choca_con_otra_publicacion_de_la_cuenta');
    else if (sug - now > 72 * 3600000 && !(why.length >= 20 && sug - now <= 30 * 86400000)) warnings.push('sugerencia_posterior_a_72h_sin_justificacion_ignorada');
    else return done(sug, 'suggestion');
  }
  // 2) siguiente hueco libre de la cuenta, día por día (hora local de Chile)
  const slots = SLOTS[o.channel] || SLOTS.linkedin_page;
  const [y, m, d] = schedDayKey(now, tz).split('-').map(Number);
  for (let k = 0; k <= 21; k++) {
    const day = new Date(Date.UTC(y, m - 1, d + k));
    for (const s of slots) {
      const [hh, mm] = s.split(':').map(Number);
      const ms = schedZonedToUtc(day.getUTCFullYear(), day.getUTCMonth() + 1, day.getUTCDate(), hh, mm, tz);
      if (ms >= minMs && free(ms)) { const r = done(ms, 'slot'); if (!r.within_target) r.warnings.push('sin_hueco_dentro_de_' + tier.targetH + 'h_por_otras_publicaciones_de_la_cuenta'); return r; }
    }
  }
  // 3) cuenta saturada 3 semanas: se propone el primer hueco aunque choque (nunca un +7 ciego) y se avisa
  const fb = schedZonedToUtc(y, m, d + 1, Number(slots[0].split(':')[0]), Number(slots[0].split(':')[1]), tz);
  const r = done(fb, 'slot'); r.warnings.push('cuenta_saturada_21_dias_revisar_a_mano'); return r;
}

function schedDayKey(ms, tz) {
  return new Date(ms).toLocaleDateString('en-CA', { timeZone: tz });
}

function schedTzOffsetMs(utcMs, tz) {
  const p = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }).formatToParts(new Date(utcMs));
  const g = (t) => Number(p.find((x) => x.type === t).value);
  return Date.UTC(g('year'), g('month') - 1, g('day'), g('hour'), g('minute'), g('second')) - utcMs;
}

function schedZonedToUtc(y, m, d, hh, mm, tz) {
  const guess = Date.UTC(y, m - 1, d, hh, mm);
  const first = guess - schedTzOffsetMs(guess, tz);
  return guess - schedTzOffsetMs(first, tz);
}

function growthCheckAnswer(text) {
  const t = String(text || '').trim();
  if (t.length < 120) return { ok: false, reason: 'respuesta_muy_corta_minimo_120_caracteres', length: t.length };
  if (t.length > 8000) return { ok: false, reason: 'respuesta_muy_larga_maximo_8000', length: t.length };
  return { ok: true, reason: null, length: t.length };
}

function growthFounderEvidence(answer, piece) {
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const a = norm(answer);
  const quotes = [];
  ((piece && piece.sources) || []).forEach((s) => { if (s && s.kind === 'real_work') (Array.isArray(s.evidence) ? s.evidence : []).forEach((e) => { if (e && typeof e.quote === 'string' && e.quote.trim()) quotes.push(e.quote.trim()); }); });
  const unmatched = quotes.filter((q) => norm(q).length < 15 || !a.includes(norm(q)));
  if (!quotes.length) return { ok: false, reason: 'founder_sin_cita_de_la_respuesta', matched: 0, unmatched: [] };
  if (unmatched.length) return { ok: false, reason: 'founder_cita_no_esta_en_la_respuesta', matched: quotes.length - unmatched.length, unmatched: unmatched.map((q) => q.slice(0, 60)) };
  return { ok: true, reason: null, matched: quotes.length, unmatched: [] };
}

function growthGovernor(o) {
  const x = o || {};
  const max = Number.isFinite(Number(x.max)) && Number(x.max) > 0 ? Number(x.max) : 6;
  const pending = Math.max(0, Number(x.pending) || 0);
  const origin = ['autonomous', 'explicit', 'founder_interview'].includes(x.origin) ? x.origin : 'explicit';
  const full = pending >= max;
  if (!full) return { allowed: true, warning: null, reason: null, pending, max, origin };
  if (origin === 'autonomous') return { allowed: false, warning: null, reason: 'cola_llena', pending, max, origin };
  return { allowed: true, warning: 'cola_llena_por_orden_explicita', reason: null, pending, max, origin };
}

function growthNorm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ ]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function growthNormIntel(report) {
  const errors = [];
  const x = report && typeof report === 'object' ? report : {};
  const str = (v, m) => (typeof v === 'string' ? v.trim().slice(0, m || 300) : '');
  const arr = (v, m, len) => (Array.isArray(v) ? v.map((i) => str(i, len || 240)).filter(Boolean).slice(0, m || 10) : []);
  const isUrl = (u) => /^https?:\/\/[^\s]+$/i.test(String(u || ''));
  const runId = str(x.run_id, 80);
  if (runId.length < 6) errors.push('run_id_obligatorio');
  const comps = (Array.isArray(x.competitors) ? x.competitors : []).map((c) => {
    const slug = str(c && c.slug, 60);
    const pages = (Array.isArray(c && c.pages_read) ? c.pages_read : []).map((u) => String(u || '').trim()).filter(isUrl).slice(0, 12);
    if (!slug) errors.push('competidor_sin_slug');
    else if (!pages.length) errors.push('competidor_sin_paginas_leidas:' + slug);
    return { slug, pages_read: pages, recent_topics: arr(c && c.recent_topics, 10), formats: arr(c && c.formats, 8, 120), hooks: arr(c && c.hooks, 8), offers: arr(c && c.offers, 8), resources: arr(c && c.resources, 8), repeated_messages: arr(c && c.repeated_messages, 8) };
  });
  if (!comps.length) errors.push('sin_competidores');
  const saturated = arr(x.saturated_topics, 10);
  const gaps = arr(x.gaps, 10);
  const angles = (Array.isArray(x.own_angles) ? x.own_angles : []).map((a) => ({ angle: str(a && a.angle, 300), why: str(a && a.why, 300), channel_suggestion: ['instagram', 'linkedin_page', 'linkedin_profile'].includes(a && a.channel_suggestion) ? a.channel_suggestion : null })).filter((a) => a.angle).slice(0, 8);
  if (!gaps.length && !angles.length) errors.push('sin_huecos_ni_angulos_propios');
  if (angles.some((a) => !a.why)) errors.push('angulo_propio_sin_porque');
  return { ok: errors.length === 0, errors, value: { run_id: runId, competitors: comps, saturated_topics: saturated, gaps, own_angles: angles, notes: str(x.notes, 600) } };
}

function growthPickQuestion(questions, openInterview, nowMs) {
  const now = Number(nowMs) || Date.now();
  if (openInterview && openInterview.status === 'asked' && now - Date.parse(openInterview.asked_at) < 72 * 3600000) return { reuse: true, interview: openInterview, question: null };
  const avail = (Array.isArray(questions) ? questions : []).filter((q) => q && q.status === 'available');
  avail.sort((a, b) => (b.priority || 0) - (a.priority || 0) || String(a.created_at || '').localeCompare(String(b.created_at || '')));
  return { reuse: false, interview: null, question: avail[0] || null };
}

function growthResourceRank(resources, query, opts) {
  const o = opts || {};
  const stop = new Set(['de', 'la', 'el', 'los', 'las', 'un', 'una', 'para', 'por', 'con', 'que', 'en', 'y', 'o', 'a', 'del', 'al', 'mi', 'tu', 'su', 'se', 'es', 'como', 'qué', 'cómo']);
  const toks = (t) => growthNorm(t).split(' ').filter((w) => w.length > 2 && !stop.has(w));
  const q = toks(query);
  const list = (Array.isArray(resources) ? resources : []).filter((r) => r && (r.status === 'active' || (o.includeDraft && r.status === 'draft')));
  const scored = list.map((r) => {
    const name = toks(r.name), topic = toks(r.topic), problem = toks(r.problem), aud = toks(r.audience);
    let s = 0;
    q.forEach((w) => {
      if (name.some((n) => n.startsWith(w) || w.startsWith(n))) s += 3;
      if (topic.some((n) => n.startsWith(w) || w.startsWith(n))) s += 3;
      if (problem.some((n) => n.startsWith(w) || w.startsWith(n))) s += 2;
      if (aud.some((n) => n.startsWith(w) || w.startsWith(n))) s += 1;
    });
    return { ...r, match_score: s };
  }).filter((r) => (q.length ? r.match_score > 0 : true));
  scored.sort((a, b) => b.match_score - a.match_score || String(b.created_at || '').localeCompare(String(a.created_at || '')));
  return scored.slice(0, o.limit || 5);
}

function growthUtmUrl(url, p) {
  const o = p || {};
  const src = String(o.channel || '').startsWith('linkedin') ? 'linkedin' : o.channel === 'instagram' ? 'instagram' : 'social';
  const base = String(url || '').split('#')[0];
  const sep = base.includes('?') ? '&' : '?';
  const enc = (v) => encodeURIComponent(String(v || '').slice(0, 60));
  return base + sep + 'utm_source=' + src + '&utm_medium=organic_social&utm_campaign=' + enc(o.slug) + (o.ideaKey ? '&utm_content=' + enc(o.ideaKey) : '');
}

function growthValidateResource(r) {
  const errors = [];
  const x = r && typeof r === 'object' ? r : {};
  const str = (v) => (typeof v === 'string' ? v.trim() : '');
  const TYPES = ['guia', 'checklist', 'plantilla', 'diagnostico', 'prompt', 'documento', 'comparativa', 'caso', 'herramienta', 'pagina'];
  const MODES = ['resource_link', 'dm', 'diagnostic'];
  const slug = str(x.slug);
  if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug) || slug.length > 80) errors.push('slug_invalido');
  const name = str(x.name);
  if (name.length < 5 || name.length > 120) errors.push('nombre_fuera_de_rango');
  if (!TYPES.includes(x.type)) errors.push('tipo_invalido');
  const topic = str(x.topic);
  if (topic.length < 3 || topic.length > 120) errors.push('tema_fuera_de_rango');
  const problem = str(x.problem);
  if (problem.length < 20 || problem.length > 400) errors.push('problema_debe_describir_que_resuelve_20_400');
  const mode = x.cta_mode || 'resource_link';
  if (!MODES.includes(mode)) errors.push('cta_mode_invalido');
  const ctaCopy = str(x.cta_copy);
  if (ctaCopy.length > 240) errors.push('cta_copy_largo');
  const url = str(x.url);
  const host = (/^https:\/\/([^/?#]+)/i.exec(url) || [])[1];
  if (!host) errors.push('url_https_obligatoria');
  else if (!/^(www\.)?atacamalabs\.cl$/i.test(host) && !(x.metadata && x.metadata.external === true)) errors.push('url_fuera_de_atacamalabs_cl');
  const status = x.status || 'draft';
  if (!['draft', 'active', 'retired'].includes(status)) errors.push('estado_invalido');
  const value = { slug, name, type: x.type, topic, audience: str(x.audience) || null, problem, cta_mode: mode, cta_copy: ctaCopy || null, url, status, metadata: x.metadata && typeof x.metadata === 'object' ? x.metadata : {}, created_by: str(x.created_by) || 'hermes' };
  return { ok: errors.length === 0, errors, value };
}

function edEvaluate(piece, ctx) {
  const p = piece && typeof piece === 'object' ? piece : {};
  const c = ctx && typeof ctx === 'object' ? ctx : {};
  const errors = [], warnings = [];
  let penalties = 0;
  const prof = edProfiles();
  const types = edTypes();
  const needs = edVisualNeeds();
  const str = (v) => (typeof v === 'string' ? v.trim() : '');
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const declared = str(p.editorial_type);
  let type = declared, inferred = false;
  if (declared && !types.includes(declared)) { errors.push('editorial_type_invalido:' + declared.slice(0, 30)); type = ''; }
  if (!type) { type = edInferType(p); inferred = true; if (!declared) warnings.push('editorial_type_inferido_declaralo_en_la_pieza'); }
  const ch = prof.channels[p.channel];
  const tp = prof.types[type];
  const text = str(p.hook) + '\n' + str(p.body);
  const len = text.length;
  const tn = norm(text);

  // tipo ↔ canal
  if (tp && ch && !tp.channels.includes(p.channel)) { warnings.push('tipo_no_recomendado_para_el_canal:' + type + '@' + p.channel); penalties += 3; }
  if (tp && ch && !tp.formats.includes(p.format) && p.format) warnings.push('formato_poco_habitual_para_el_tipo:' + type + '/' + p.format);

  // largo por canal (el tipo afina el rango en LinkedIn)
  if (ch) {
    const lo = p.channel === 'instagram' ? ch.chars[0] : (tp ? tp.chars[0] : ch.chars[0]);
    const hi = p.channel === 'instagram' ? ch.chars[1] : (tp ? Math.min(tp.chars[1], ch.chars[1]) : ch.chars[1]);
    if (p.channel === 'instagram') {
      const cap = len + (str(p.cta && p.cta.text) ? str(p.cta.text).length : 0);
      if (cap > 1000) errors.push('instagram_copy_largo_maximo_1000_caracteres_el_peso_va_en_las_slides');
      else if (cap > hi) { warnings.push('instagram_copy_largo:' + cap); penalties += 4; }
    } else if (len > hi) { warnings.push('largo_excesivo_para_el_tipo:' + len + '>' + hi); penalties += 3; }
    else if (len < lo * 0.5 && p.format === 'texto') warnings.push('largo_corto_para_el_tipo:' + len + '<' + lo);
  }

  // voz por canal
  const firstSing = (tn.match(/\b(yo|mi|mis|me|he|hice|aprendi|aprendimos|pense|decidi|construi|construyo|vi|note|descubri|escribo|creo|trabajo|estoy)\b/g) || []).length;
  const corporate = tn.match(/nos complace|estamos orgullosos|es un placer anunciar|lider en el mercado|solucion integral|nuestra solucion|nuestros servicios|ofrecemos soluciones|a la vanguardia|llevamos tu empresa|contactanos hoy/g) || [];
  if (p.channel === 'linkedin_profile') {
    if (corporate.length) { warnings.push('tono_corporativo_en_perfil_personal'); penalties += Math.min(8, 4 * corporate.length); }
    if (firstSing < 2) { warnings.push('perfil_personal_sin_voz_en_primera_persona'); penalties += 5; }
  }
  if (p.channel === 'linkedin_page' && firstSing >= 6 && /\byo\b/.test(tn)) { warnings.push('pagina_de_empresa_con_voz_demasiado_personal'); penalties += 2; }

  // decisión visual
  const v = p.visual && typeof p.visual === 'object' ? p.visual : null;
  let need = v ? str(v.need) : '';
  let vInferred = false;
  if (v && !needs.includes(need)) { errors.push('visual_need_invalido:' + need.slice(0, 30)); need = ''; }
  if (!need) {
    vInferred = true;
    need = p.format === 'texto' ? 'none' : p.format === 'carrusel' ? 'carousel' : p.format === 'reel' || p.format === 'demo' ? 'short_video' : (tp ? tp.visual.options.find((o) => o !== 'none') : '') || 'editorial_image';
    warnings.push('visual_sin_decision_explicita_declara_visual.need');
  }
  const IMG = ['editorial_image', 'conceptual_image', 'diagram', 'process_flow', 'architecture', 'comparison', 'before_after', 'framework', 'checklist', 'chart', 'annotated_screenshot', 'resource_visual', 'typographic'];
  if (!vInferred) {
    if (need === 'none' && p.format !== 'texto') errors.push('visual_none_pero_el_formato_pide_medio:' + p.format);
    if (need !== 'none' && p.format === 'texto') errors.push('formato_texto_con_visual_declarado:' + need + '_usa_imagen_o_carrusel_o_visual_none');
    if (need === 'carousel' && p.format !== 'carrusel') errors.push('visual_carousel_requiere_formato_carrusel');
    if (need === 'short_video' && !['reel', 'demo'].includes(p.format)) errors.push('visual_short_video_requiere_formato_reel_o_demo');
    if (IMG.includes(need) && !['imagen', 'carrusel'].includes(p.format)) errors.push('visual_' + need + '_requiere_formato_imagen_o_carrusel');
    if (tp && tp.visual.need === 'required' && need === 'none') warnings.push('este_tipo_suele_necesitar_visual:' + type);
    if (v && !str(v.rationale) && need !== 'none') warnings.push('visual_sin_justificacion');
    if (v && need === 'none' && !str(v.rationale)) warnings.push('visual_none_sin_justificacion');
  }
  if (p.channel === 'instagram' && need === 'none') errors.push('instagram_requiere_visual');
  // reglas de marca en lo que describe el visual (se permite nombrar lo que se EVITA: «sin robots»)
  const vtext = norm(str(p.visual_direction) + ' ' + str(v && v.rationale) + ' ' + str(v && v.prompt));
  const BAD = ['robot', 'holograma', 'cyber', 'neon', 'circuito', 'cripto', 'blockchain', 'matrix', 'cerebro digital', 'glow'];
  BAD.forEach((w) => {
    let i = vtext.indexOf(w);
    while (i >= 0) {
      const before = vtext.slice(Math.max(0, i - 28), i);
      if (!/\b(sin|no|ni|evit\w*|nunca|nada de|ningun\w*)\b/.test(before)) { errors.push('visual_viola_brand:' + w); break; }
      i = vtext.indexOf(w, i + w.length);
    }
  });
  if (/\bhero\b|landing|banner de (la )?web/.test(vtext)) { warnings.push('el_visual_parece_un_hero_de_la_web_las_redes_no_son_la_landing'); penalties += 2; }
  const comp = str(v && v.composition);
  const recent = Array.isArray(c.recentVisuals) ? c.recentVisuals.slice(0, 3).map((x) => norm(x)) : [];
  if (comp && recent.length >= 2 && recent.slice(0, 2).every((x) => x === norm(comp))) { warnings.push('composicion_repetida_en_las_ultimas_piezas:' + comp.slice(0, 30)); penalties += 2; }
  return { type, inferred, errors, warnings, penalties: Math.min(penalties, 12), visual: { need, inferred: vInferred }, profile: ch ? ch.label : null };
}

function edInferType(piece) {
  const p = piece && typeof piece === 'object' ? piece : {};
  const cat = String(p.category || '');
  const kinds = (Array.isArray(p.sources) ? p.sources : []).map((s) => s && s.kind);
  if (cat === 'Founder' || p.channel === 'linkedin_profile') return kinds.includes('real_work') ? 'build_in_public' : 'founder';
  if (cat === 'Noticia') return 'news_explainer';
  if (cat === 'Caso') return 'case';
  if (cat === 'Demo') return 'demo';
  if (cat === 'Evergreen') return p.cta_mode === 'resource_link' ? 'resource' : 'framework';
  return 'educational';
}

function edPlan(input) {
  const x = input && typeof input === 'object' ? input : {};
  const sig = x.signal && typeof x.signal === 'object' ? x.signal : {};
  const prof = edProfiles();
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const toks = (s) => norm(s).split(' ').filter((w) => w.length > 3);
  const notes = [];
  const w = x.week || {};
  const room = Math.max(0, (Number(w.target) || 5) - (Number(w.coverage) || 0));
  const topicTokens = toks(sig.topic);
  const covered = (Array.isArray(x.recent) ? x.recent : []).filter((r) => ['in_review', 'scheduled', 'approved', 'published'].includes(r.status)).find((r) => {
    const rt = toks(r.topic); if (!topicTokens.length || !rt.length) return false;
    const inter = topicTokens.filter((t) => rt.includes(t)).length; return inter / Math.min(topicTokens.length, rt.length) >= 0.6;
  });
  const urgent = sig.urgent === true;
  const kindType = edSignalType(sig);
  const explicit = x.explicit === true;
  const base = { signal: String(sig.topic || '').slice(0, 140), week: { done: w.done, in_review: w.in_review, coverage: w.coverage, target: w.target, max: w.max, runway_days: w.runway_days, state: w.state_label || w.state } };

  // ¿publicar o no?
  let publish = true, reason = 'vale la pena: hay espacio en la semana y la señal no está cubierta';
  const pending = Number(x.pending) || 0, maxPending = Number(x.max_pending) || 6;
  if (!String(sig.topic || '').trim()) return { ...base, publish: false, reason: 'falta el tema de la señal', proposals: [], notes };
  if (covered) { publish = false; reason = 'ya hay una pieza parecida (' + covered.status + '): «' + String(covered.topic).slice(0, 80) + '». Solo con un hecho nuevo.'; }
  else if (pending >= maxPending && !explicit) { publish = false; reason = 'la cola de revisión está llena (' + pending + '/' + maxPending + '): primero se revisa lo pendiente'; }
  else if (!explicit && !urgent && (w.covered || (Number(w.runway_days) || 0) >= (Number(w.runway_max) || 5))) { publish = false; reason = w.covered ? 'la semana está cubierta (' + w.coverage + '/' + w.target + '): se guarda la señal, no se fabrica una pieza normal' : 'ya hay ' + w.runway_days + ' días de contenido por delante'; }
  else if (urgent && (Number(w.coverage) || 0) >= (Number(w.max) || 6) && !explicit) { publish = false; reason = 'aun siendo urgente, ya se llegó al máximo normal de la semana (' + w.max + ')'; }
  else if (explicit && (w.covered || pending >= maxPending)) notes.push('orden explícita: pasa por encima del ritmo/cola, pero Christian verá la advertencia');
  if (!publish) return { ...base, publish, reason, urgency: urgent ? 'urgent' : 'normal', proposals: [], notes };

  // canales que de verdad encajan con esta señal
  const personal = sig.personal === true || ['founder', 'build_in_public', 'customer_problem', 'opinion'].includes(kindType);
  const visualizable = sig.visualizable !== false && !['opinion', 'market_signal'].includes(kindType);
  const recentByChannel = {};
  (Array.isArray(x.recent) ? x.recent : []).forEach((r) => { (recentByChannel[r.channel] = recentByChannel[r.channel] || []).push(r.editorial_type || ''); });
  const lastTypes = (ch) => (recentByChannel[ch] || []).slice(0, 3);
  const pick = (ch, options) => options.find((t) => !lastTypes(ch).includes(t)) || options[0];
  const proposals = [];
  const resource = Array.isArray(x.resources) && x.resources.length ? x.resources[0] : null;
  const days = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];

  if (personal) {
    const type = pick('linkedin_profile', kindType === 'customer_problem' ? ['customer_problem', 'founder', 'opinion'] : kindType === 'opinion' ? ['opinion', 'founder'] : ['build_in_public', 'founder', 'opinion']);
    proposals.push({ channel: 'linkedin_profile', account: prof.channels.linkedin_profile.label, editorial_type: type, role: prof.channels.linkedin_profile.role, tone: prof.channels.linkedin_profile.tone, format: 'texto',
      angle_directive: 'Desde la experiencia real de Christian: el problema que vivió, la decisión que tomó y lo que aprendió (primera persona, concreto, sin vender). No inventes vivencias: si faltan detalles, usa Founder Interview (entrevistame).',
      length_chars: prof.types[type].chars, visual: { need: 'none', options: prof.types[type].visual.options, why: 'Un buen post personal puede ser solo texto; imagen solo si hay una captura anotada o un diagrama que de verdad ayuda' }, cta_mode: 'none', cta_why: 'Reflexión/aprendizaje: sin CTA comercial', resource: null });
  }
  {
    const opts = kindType === 'news_explainer' ? ['news_explainer', 'educational'] : kindType === 'resource' ? ['resource', 'framework'] : kindType === 'demo' ? ['demo', 'process'] : ['educational', 'framework', 'process', 'comparison'];
    const type = pick('linkedin_page', opts);
    const tpf = prof.types[type];
    const needsVisual = tpf.visual.need === 'required' || tpf.visual.need === 'recommended';
    const useResource = resource && ['resource', 'framework', 'educational'].includes(type);
    proposals.push({ channel: 'linkedin_page', account: prof.channels.linkedin_page.label, editorial_type: type, role: prof.channels.linkedin_page.role, tone: prof.channels.linkedin_page.tone, format: needsVisual ? (tpf.formats.includes('carrusel') && type !== 'framework' ? 'carrusel' : 'imagen') : 'texto',
      angle_directive: 'Autoridad de empresa: explica el tema como lo haría quien construye estos sistemas (qué necesita, cómo se conecta, dónde sí y dónde no). Estructura clara (4–5 componentes o pasos), sin copiar el enfoque personal de Christian ni el carrusel de Instagram.',
      length_chars: tpf.chars, visual: { need: needsVisual ? tpf.visual.options[0] : 'none', options: tpf.visual.options, why: needsVisual ? 'Una estructura (' + tpf.visual.options[0] + ') se entiende mejor dibujada que contada' : 'El texto solo alcanza para esta idea' },
      cta_mode: useResource ? 'resource_link' : (tpf.cta.includes('diagnostic') && type !== 'news_explainer' ? 'diagnostic' : 'none'), cta_why: useResource ? 'Hay un recurso existente que extiende el tema: reutilizarlo antes de crear otro' : 'Sin recurso que aporte, no se fuerza un CTA', resource: useResource ? { id: resource.id, slug: resource.slug, name: resource.name } : null });
  }
  if (visualizable && x.include_instagram !== false) {
    const type = pick('instagram', kindType === 'customer_problem' ? ['customer_problem', 'process'] : ['educational', 'process', 'comparison', 'framework']);
    proposals.push({ channel: 'instagram', account: prof.channels.instagram.label, editorial_type: type, role: prof.channels.instagram.role, tone: prof.channels.instagram.tone, format: 'carrusel',
      angle_directive: 'Carrusel de 6–7 slides que se entienda sin leer el caption: una idea por slide (conversar ≠ trabajar → pieza 1 → pieza 2 → … → cierre). Caption breve (≤ 600 caracteres), sin repetir el post largo de LinkedIn ni llenar slides de texto.',
      length_chars: prof.channels.instagram.chars, visual: { need: 'carousel', options: ['carousel', 'process_flow', 'before_after', 'checklist'], why: 'Instagram es visual primero: se renderiza con el renderer de carruseles (texto exacto), no con generación de imagen' }, cta_mode: 'dm', cta_why: 'Instagram no enlaza en el caption: DM o link en bio', resource: null, render: 'render-pending (manual)' });
  }
  // el espacio disponible limita cuántas cuentas se cubren: primero la que mejor encaja con el origen de la señal
  const order = personal ? ['linkedin_profile', 'linkedin_page', 'instagram'] : ['linkedin_page', 'instagram', 'linkedin_profile'];
  proposals.sort((a, b) => order.indexOf(a.channel) - order.indexOf(b.channel));
  const limit = explicit ? proposals.length : Math.max(1, Math.min(proposals.length, room || 1));
  if (limit < proposals.length) notes.push('el ritmo semanal solo deja espacio para ' + limit + ' pieza(s): se proponen las que mejor encajan; el resto queda como idea para otra semana');
  const dow = new Date(Number(x.now) || 0).getUTCDay();
  const guide = { 1: 'dolor/problema real', 2: 'educativo/cómo funciona', 3: 'caso/construcción/aprendizaje', 4: 'opinión/mercado/tendencia', 5: 'recurso/checklist/guía' }[dow];
  if (guide) notes.push('guía de variedad de hoy (' + days[dow] + '): ' + guide + ' (orientativa, no obligatoria)');
  const urgency = urgent ? 'urgent' : ['resource', 'framework', 'process'].includes(kindType) ? 'evergreen' : 'normal';
  return { ...base, publish: true, reason, urgency, window_hours: urgency === 'urgent' ? 24 : urgency === 'evergreen' ? 72 : 48, signal_type: kindType, proposals: proposals.slice(0, limit), notes };
}

